export function evaluate({ inputs, time }) {
 const g = 9.8, u = inputs.launchSpeed;
 const T = 2 * u / g;
 const t = Math.max(0, Math.min(T, time));
 const v = u - g * t;
 const h = u * t - g * t * t / 2;
 const apexTime = u / g, apexHeight = u * u / (2 * g);
 const top = Math.abs(t - apexTime) < 0.006;
 const vv = top ? 0 : v;
 const y0 = 370, sc = 55;
 const by = y0 - h * sc * 1.0 - 14;
 const bx = 300;
 const objs = [];
 objs.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 600, h: 370, title: 'Tossed ball', state: top ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down') }));
 objs.push(sdk.axis('axis.h', { x: 90, y: y0, length: 300, orientation: 'y', min: 0, max: 5.45, ticks: [0, 1, 2, 3, 4, 5], label: 'Height', unit: 'm' }));
 objs.push(sdk.line('guide.launch', 100, y0, 520, y0, { role: 'neutral' }));
 objs.push(sdk.circle('ball.toss', bx, by, 28, { role: 'observed' }));
 objs.push(...sdk.vector('vec.v', { x: bx + 40, y: by }, { value: vv, direction: 'up' }, { scale: 14, minLength: 12, label: 'v', role: 'input' }));
 objs.push(...sdk.vector('vec.a', { x: bx - 40, y: by }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
 objs.push(sdk.callout(bx + 110, by - 30, [top ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down'), 'Gravity pulls down'], { id: 'callout.toss' }));
 return { frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: top ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down') }, { id: 'gravityState', value: 'Gravity pulls down' }] }, quantities: { launchSpeed: u, gravity: g, apexTime, apexHeight, velocity: v, height: h } };
}
